{"code":"from typing import Any

from fastapi import FastAPI, HTTPException, Request, status
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict, Field

app = FastAPI()
app.state.config = {
    "PAGE_SIZE": 3,
    "FEATURE_VERBOSE": True,
    "SERVICE_NAME": "reporting",
    "MAX_RANGE_DAYS": 30,
}

_ROWS = [{"id": i, "value": i * 10} for i in range(1, 11)]


class ReportIn(BaseModel):
    model_config = ConfigDict(extra="ignore")

    days: int = 7


@app.get("/config")
def show_config() -> dict[str, Any]:
    config = app.state.config
    return {
        "service": config["SERVICE_NAME"],
        "page_size": config["PAGE_SIZE"],
        "verbose": config["FEATURE_VERBOSE"],
    }


@app.get("/rows")
def rows(size: int | None = None) -> dict[str, Any]:
    config = app.state.config
    effective_size = size or config["PAGE_SIZE"]
    page = _ROWS[:effective_size]
    payload: dict[str, Any] = {"rows": page}
    if config["FEATURE_VERBOSE"]:
        payload["meta"] = {"returned": len(page), "total": len(_ROWS)}
    return payload


@app.post("/report", status_code=status.HTTP_202_ACCEPTED)
def report(data: ReportIn) -> JSONResponse | dict[str, Any]:
    config = app.state.config
    days = data.days
    if not isinstance(days, int):
        raise HTTPException(status_code=400, detail={"error": "days must be an integer"})
    if days > config["MAX_RANGE_DAYS"]:
        raise HTTPException(
            status_code=400,
            detail={"error": "range too large", "max": config["MAX_RANGE_DAYS"]},
        )
    return {"service": config["SERVICE_NAME"], "days": days}
"}

{"code":"from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field

app = FastAPI()

_ACCOUNTS = {"a1": {"id": "a1", "balance": 100}}


class InsufficientFunds(Exception):
    def __init__(self, needed, available):
        super().__init__("insufficient funds")
        self.needed = needed
        self.available = available


class WithdrawRequest(BaseModel):
    amount: int = Field(...)


@app.exception_handler(InsufficientFunds)
async def on_insufficient_funds(request: Request, exc: InsufficientFunds):
    return JSONResponse(
        status_code=409,
        content={"error": "insufficient_funds", "needed": exc.needed, "available": exc.available},
    )


@app.exception_handler(HTTPException)
async def on_http_error(request: Request, exc: HTTPException):
    return JSONResponse(
        status_code=exc.status_code,
        content={"error": "http_error", "status": exc.status_code, "message": exc.detail},
    )


@app.exception_handler(404)
async def on_not_found(request: Request, exc):
    return JSONResponse(
        status_code=404,
        content={"error": "http_error", "status": 404, "message": "Not Found"},
    )


@app.exception_handler(405)
async def on_method_not_allowed(request: Request, exc):
    return JSONResponse(
        status_code=405,
        content={"error": "http_error", "status": 405, "message": "Method Not Allowed"},
    )


@app.get("/accounts/{account_id}")
async def get_account(account_id: str):
    account = _ACCOUNTS.get(account_id)
    if account is None:
        raise HTTPException(status_code=404, detail="account")
    return account


@app.post("/accounts/{account_id}/withdraw")
async def withdraw(account_id: str, payload: WithdrawRequest):
    account = _ACCOUNTS.get(account_id)
    if account is None:
        raise HTTPException(status_code=404, detail="account")
    amount = payload.amount
    if amount <= 0:
        raise HTTPException(status_code=400, detail="bad_amount")
    if amount > account["balance"]:
        raise InsufficientFunds(amount, account["balance"])
    return {"id": account_id, "withdrawn": amount, "balance": account["balance"] - amount}
"}

{"code":"from fastapi import Depends, FastAPI, Header, HTTPException, Request, status
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field

app = FastAPI()

_TOKENS = {"secret-token": {"user": "ana", "role": "admin"}}
_NOTES = {1: {"id": 1, "owner": "ana", "text": "first"}}


class NoteCreate(BaseModel):
    text: str = Field(..., min_length=1)


async def authenticate(x_api_token: str | None = Header(default=None, alias="X-Api-Token")):
    if not x_api_token:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail={"error": "missing token", "code": "AUTH_001"},
        )
    identity = _TOKENS.get(x_api_token)
    if identity is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail={"error": "invalid token", "code": "AUTH_002"},
        )
    return identity


@app.exception_handler(HTTPException)
async def http_exception_handler(request: Request, exc: HTTPException):
    if isinstance(exc.detail, dict):
        return JSONResponse(status_code=exc.status_code, content=exc.detail)
    return JSONResponse(status_code=exc.status_code, content={"detail": exc.detail})


@app.get("/api/v1/whoami")
async def whoami(identity: dict = Depends(authenticate)):
    return {"user": identity["user"], "role": identity["role"]}


@app.get("/api/v1/notes/{note_id}")
async def get_note(note_id: int, identity: dict = Depends(authenticate)):
    note = _NOTES.get(note_id)
    if note is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Not Found")
    if note["owner"] != identity["user"]:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail={"error": "forbidden"},
        )
    return note


@app.post("/api/v1/notes", status_code=status.HTTP_201_CREATED)
async def create_note(payload: NoteCreate, identity: dict = Depends(authenticate)):
    if not payload.text:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
            detail={"error": "text is required", "code": "VAL_001"},
        )
    return {"id": 2, "owner": identity["user"], "text": payload.text}
"}

{"code":""""Small inventory service. Synthetic case, written for this benchmark.

Exercises: JSON body handling, manual validation with explicit 400s, a query
parameter with a default, path converters, and 404 on a missing resource.
"""

from fastapi import FastAPI, HTTPException, Query, Request, status
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict, Field, ValidationError

app = FastAPI()
app.state.page_size = 2

_ITEMS = {
    1: {"id": 1, "name": "bolt", "qty": 40},
    2: {"id": 2, "name": "nut", "qty": 12},
    3: {"id": 3, "name": "washer", "qty": 7},
}


class Item(BaseModel):
    model_config = ConfigDict(extra="ignore")

    id: int
    name: str
    qty: int


class CreateItemRequest(BaseModel):
    model_config = ConfigDict(extra="ignore")

    name: str
    qty: int = 0


@app.get("/items")
def list_items(limit: int | None = Query(default=None)):
    effective_limit = limit or app.state.page_size
    items = list(_ITEMS.values())[:effective_limit]
    return {"items": items, "count": len(items)}


@app.get("/items/{item_id}")
def get_item(item_id: int):
    item = _ITEMS.get(item_id)
    if item is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail={"error": "item not found"})
    return item


@app.post("/items", status_code=status.HTTP_201_CREATED)
async def create_item(request: Request):
    try:
        data = await request.json()
    except Exception:
        return JSONResponse({"error": "body must be JSON"}, status_code=status.HTTP_400_BAD_REQUEST)

    if not data:
        return JSONResponse({"error": "body must be JSON"}, status_code=status.HTTP_400_BAD_REQUEST)

    if "name" not in data:
        return JSONResponse({"error": "name is required"}, status_code=status.HTTP_400_BAD_REQUEST)

    if not isinstance(data["name"], str):
        return JSONResponse({"error": "name must be a string"}, status_code=status.HTTP_400_BAD_REQUEST)

    qty = data.get("qty", 0)
    new_id = max(_ITEMS) + 1
    return {"id": new_id, "name": data["name"], "qty": qty}


@app.delete("/items/{item_id}")
def delete_item(item_id: int):
    if item_id not in _ITEMS:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail={"error": "item not found"})
    return {"deleted": item_id}


@app.get("/health")
def health():
    return {"status": "ok", "page_size": app.state.page_size}
"}

