{"code":"from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict, Field
from typing import List, Literal, Union

app = FastAPI()

_KNOWN = {"a", "b", "c"}


class ResultOk(BaseModel):
    model_config = ConfigDict(extra="forbid")
    index: int
    status: Literal["ok"]


class ResultUnknown(BaseModel):
    model_config = ConfigDict(extra="forbid")
    index: int
    status: Literal["unknown"]


class ResultInvalid(BaseModel):
    model_config = ConfigDict(extra="forbid")
    index: int
    status: Literal["invalid"]
    reason: str


Result = Union[ResultOk, ResultUnknown, ResultInvalid]


class BulkVerifyResponse(BaseModel):
    model_config = ConfigDict(extra="forbid")
    results: List[Result]
    failed: int


class LimitsResponse(BaseModel):
    model_config = ConfigDict(extra="forbid")
    max_items: int = Field(default=100)
    known: List[str]


@app.post("/bulk/verify")
async def bulk_verify(request: Request):
    try:
        payload = await request.json()
    except Exception:
        return JSONResponse({"error": "body must be JSON"}, status_code=400)

    if not isinstance(payload, list):
        return JSONResponse({"error": "body must be a JSON array"}, status_code=400)
    if not payload:
        return JSONResponse({"error": "array must not be empty"}, status_code=400)

    results = []
    for index, key in enumerate(payload):
        if not isinstance(key, str):
            results.append({"index": index, "status": "invalid", "reason": "not a string"})
        elif key in _KNOWN:
            results.append({"index": index, "status": "ok"})
        else:
            results.append({"index": index, "status": "unknown"})

    failed = sum(1 for r in results if r["status"] != "ok")
    status_code = 200 if failed == 0 else 207
    return JSONResponse({"results": results, "failed": failed}, status_code=status_code)


@app.get("/bulk/limits")
async def limits():
    return JSONResponse({"max_items": 100, "known": sorted(_KNOWN)})
"}

{"code":""""Trailing-slash and redirect behaviour. Synthetic case for this benchmark.

Exercises: Flask's strict_slashes redirect, an explicitly non-strict route, and
a route that only exists with the slash. Clients follow these redirects today.
"""

from fastapi import FastAPI
from fastapi.responses import JSONResponse

app = FastAPI()


@app.get("/reports/")
def list_reports():
    # Declared WITH a trailing slash: FastAPI/Starlette redirects /reports to /reports/.
    return JSONResponse({"reports": ["daily", "weekly"]})


@app.get("/status")
def status():
    # Declared WITHOUT a trailing slash: /status/ returns 404.
    return JSONResponse({"status": "up"})


@app.get("/jobs", include_in_schema=True)
@app.get("/jobs/", include_in_schema=False)
def jobs():
    return JSONResponse({"jobs": []})


@app.get("/queue/{name}")
def queue(name: str):
    return JSONResponse({"queue": name, "depth": 0})
"}

{"code":"from fastapi import FastAPI, Header, HTTPException, Request, Response, status
from pydantic import BaseModel, Field

app = FastAPI()


class Doc(BaseModel):
    id: str
    title: str
    version: int


class ErrorResponse(BaseModel):
    error: str
    code: str | None = None
    expected: int | None = None


class PatchDocRequest(BaseModel):
    title: str = Field(..., min_length=1)


_DOCS: dict[str, Doc] = {"d1": Doc(id="d1", title="spec", version=3)}


@app.get("/docs/{doc_id}", response_model=Doc)
def get_doc(doc_id: str, response: Response):
    doc = _DOCS.get(doc_id)
    if doc is None:
        raise HTTPException(status_code=404, detail={"error": "doc not found"})
    response.headers["ETag"] = f'W/"{doc.version}"'
    return doc


@app.patch("/docs/{doc_id}", response_model=Doc)
def patch_doc(
    doc_id: str,
    request: Request,
    response: Response,
    if_match: str | None = Header(default=None, alias="If-Match"),
):
    doc = _DOCS.get(doc_id)
    if doc is None:
        raise HTTPException(status_code=404, detail={"error": "doc not found"})

    if not if_match:
        raise HTTPException(
            status_code=status.HTTP_428_PRECONDITION_REQUIRED,
            detail={"error": "If-Match header is required", "code": "PRECONDITION_REQUIRED"},
        )
    if if_match != f'W/"{doc.version}"':
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail={"error": "version conflict", "expected": doc.version},
        )

    data = request.json()
    # FastAPI request.json() is async; use request body parsing via Pydantic instead.
    # This branch is kept unreachable because the endpoint signature below handles parsing.
    raise HTTPException(status_code=500, detail="unreachable")


@app.patch("/docs/{doc_id}", response_model=Doc)
async def patch_doc_async(
    doc_id: str,
    payload: PatchDocRequest,
    response: Response,
    if_match: str | None = Header(default=None, alias="If-Match"),
):
    doc = _DOCS.get(doc_id)
    if doc is None:
        raise HTTPException(status_code=404, detail={"error": "doc not found"})

    if not if_match:
        raise HTTPException(
            status_code=status.HTTP_428_PRECONDITION_REQUIRED,
            detail={"error": "If-Match header is required", "code": "PRECONDITION_REQUIRED"},
        )
    if if_match != f'W/"{doc.version}"':
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail={"error": "version conflict", "expected": doc.version},
        )

    updated = Doc(id=doc.id, title=payload.title, version=doc.version + 1)
    response.headers["ETag"] = f'W/"{updated.version}"'
    return updated
"}

