{"code":""""Trailing-slash and redirect behaviour. Synthetic case for this benchmark.

Exercises: Flask's strict_slashes redirect, an explicitly non-strict route, and
a route that only exists with the slash. Clients follow these redirects today.
"""

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, RedirectResponse

app = FastAPI()


@app.middleware("http")
async def preserve_flask_trailing_slash_behavior(request: Request, call_next):
    path = request.scope.get("path", "")
    method = request.method

    # Flask-style redirect for /reports -> /reports/ (308)
    if method == "GET" and path == "/reports":
        return RedirectResponse(url="/reports/", status_code=308)

    # Flask-style 404 for /status/ when only /status exists
    if method == "GET" and path == "/status/":
        return JSONResponse(content={"detail": "Not Found"}, status_code=404)

    response = await call_next(request)
    return response


@app.get("/reports/")
async def list_reports():
    return JSONResponse(content={"reports": ["daily", "weekly"]})


@app.get("/status")
async def status():
    return JSONResponse(content={"status": "up"})


@app.get("/jobs")
async def jobs():
    return JSONResponse(content={"jobs": []})


@app.get("/queue/{name}")
async def queue(name: str):
    return JSONResponse(content={"queue": name, "depth": 0})
"}

{"code":"from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

app = FastAPI()

_EVENTS = [{"id": i, "kind": "click"} for i in range(1, 26)]
MAX_PER_PAGE = 10


@app.get("/events")
async def events(request: Request):
    page_raw = request.query_params.get("page", "1")
    per_page_raw = request.query_params.get("per_page", "5")

    try:
        page = int(page_raw)
    except (TypeError, ValueError):
        page = 1

    try:
        per_page = int(per_page_raw)
    except (TypeError, ValueError):
        per_page = 5

    if page < 1:
        return JSONResponse(content={"error": "page must be >= 1"}, status_code=400)
    if per_page > MAX_PER_PAGE:
        per_page = MAX_PER_PAGE

    start = (page - 1) * per_page
    rows = _EVENTS[start : start + per_page]
    total = len(_EVENTS)
    last_page = (total + per_page - 1) // per_page

    response = JSONResponse(content={"events": rows, "page": page, "per_page": per_page}, status_code=200)
    response.headers["X-Total-Count"] = str(total)
    links = [
        f'</events?page=1&per_page={per_page}>; rel="first"',
        f'</events?page={last_page}&per_page={per_page}>; rel="last"',
    ]
    if page < last_page:
        links.append(f'</events?page={page + 1}&per_page={per_page}>; rel="next"')
    response.headers["Link"] = ", ".join(links)
    return response
"}

